var a=`1331-papa-a-la-huancaina`;var n=`world-1331`;var t=`PE`;var s=`south-america`;var r=4;var o=58;var l={en:`Papa a la Huancaína`,ua:`Папа а ла уанкаїна`};var g={en:`Papa a la Huancaína is a dish from Peru featuring potato, queso fresco, aji amarillo paste, evaporated milk. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Папа а ла уанкаїна, страва кухні країни Перу з такими основними складниками: картопля, кесо фреско, паста ахі амарильйо, концентроване молоко без цукру. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Cook the listed ingredients in simmering water for about 27 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 27 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:27,i:[[`potato`,760,`g`],[`water`,1100,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`queso-fresco`,290,`g`],[`aji-amarillo-paste`,65,`g`],[`evaporated-milk`,270,`ml`],[`cracker-crumbs`,75,`g`]]},{en:`Boil the eggs for about 11 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 11 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:11,i:[[`chicken-egg`,3,`pcs`]]},{en:`Arrange the fully cooked and prepared parts of the dish on plates or in the intended serving vessel, adding the listed toppings or accompaniments just before serving.`,ua:`Зберіть повністю приготовані частини страви на тарілках або в посуді для подавання, додавши зазначені топінги та доповнення безпосередньо перед подаванням.`,t:[`layered-assembly`,`garnishing`],m:8,i:[[`lettuce`,150,`g`],[`black-olives`,85,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,22,`g`]]}];var m={slug:a,id:n,country:`PE`,region:s,servings:4,minutes:58,title:l,text:g,steps:d};export{t as country,m as default,n as id,o as minutes,s as region,r as servings,a as slug,d as steps,g as text,l as title};